python3 - "$dir/p9" <<'"'PY'
from html.parser import HTMLParser
from pathlib import Path
import sys
class P(HTMLParser):
    def __init__(self): super().__init__(); self.in_title=0; self.href=None; self.buf=[]; self.rows=[]
    def handle_starttag(self,t,attrs):
        d=dict(attrs)
        if 'views-field-title' in d.get('class','').split(): self.in_title+=1
        if self.in_title and t=='a': self.href=d.get('href'); self.buf=[]
    def handle_data(self,d):
        if self.in_title and self.href is not None: self.buf.append(d)
    def handle_endtag(self,t):
        if t=='a' and self.in_title and self.href is not None:
            self.rows.append((self.href,' '.join(' '.join(self.buf).split()))); self.href=None; self.buf=[]
        if t=='div' and self.in_title: self.in_title-=1
p=P(); p.feed(Path(sys.argv[1]).read_text(errors='ignore'))
for href,title in p.rows: print(f'{title} | https://online.iitk.ac.in{href}')
